using System.Collections.Concurrent;
using ICorDebugSharp;

namespace SharpDbg.Infrastructure.Debugger;

/// <summary>
/// Symbols for a module that has no PDB, supplied by the DAP client instead of generated by the adapter.
/// </summary>
/// <remarks>
/// With <see cref="DecompileExternalCode"/> turned off the adapter never decompiles by itself. A module without symbols that
/// the debugger needs symbols for raises <see cref="OnSymbolsNeeded"/>, and the calling thread waits (as it always did while
/// decompiling) until the client answers through <see cref="ProvideSymbols"/>, or <see cref="ClientSymbolsTimeout"/> passes.
/// The client may also provide the symbols before they are needed.
/// </remarks>
public partial class ManagedDebugger
{
	/// <summary>
	/// True (the default): the adapter generates a PDB by decompiling a module that has none. False: it only uses symbols the
	/// client supplies, so a client without a decompiler gets no decompilation at all.
	/// </summary>
	public bool DecompileExternalCode { get; set; } = true;

	/// <summary>How long a thread waits for the client to supply symbols before the module is treated as having none.</summary>
	public TimeSpan ClientSymbolsTimeout { get; set; } = DefaultClientSymbolsTimeout;

	public static readonly TimeSpan DefaultClientSymbolsTimeout = TimeSpan.FromSeconds(180);

	/// <summary>A module without symbols needs them: module name, module path, MVID.</summary>
	public event Action<string, string, Guid>? OnSymbolsNeeded;

	// The PDB path the client supplied per MVID; null when the client declined (or the wait timed out).
	private readonly ConcurrentDictionary<Guid, string?> _clientSymbols = new();
	private readonly ConcurrentDictionary<Guid, TaskCompletionSource<string?>> _symbolWaiters = new();

	/// <summary>
	/// The client's answer for a module: the path of a PDB, or null/empty to say it has none. Safe to call from any thread and
	/// does not touch debugger state, so it can run while the thread that asked is still waiting.
	/// </summary>
	public void ProvideSymbols(Guid mvid, string? pdbPath)
	{
		var path = string.IsNullOrEmpty(pdbPath) ? null : pdbPath;
		_clientSymbols[mvid] = path;
		if (_symbolWaiters.TryRemove(mvid, out var waiter)) waiter.TrySetResult(path);
	}

	/// <summary>
	/// Releases every thread waiting for symbols (the session is ending). Called before the request lock is taken, because a waiting
	/// thread holds it.
	/// </summary>
	public void CancelSymbolWaiters()
	{
		foreach (var mvid in _symbolWaiters.Keys)
		{
			if (_symbolWaiters.TryRemove(mvid, out var waiter)) waiter.TrySetResult(null);
		}
	}

	private bool TryGetClientSymbols(ModuleInfo moduleInfo)
	{
		var mvid = moduleInfo.Module.GetMetaDataInterface<IMetaDataImport>().ScopeProps.pmvid;
		if (!_clientSymbols.TryGetValue(mvid, out var pdbPath))
		{
			var needed = OnSymbolsNeeded;
			if (needed is null) return false;

			var waiter = _symbolWaiters.GetOrAdd(mvid, _ => new TaskCompletionSource<string?>(TaskCreationOptions.RunContinuationsAsynchronously));
			// ProvideSymbols stores the answer before it looks for a waiter, so an answer that arrived between the miss above and the
			// waiter just registered is found here instead of being waited for forever
			if (_clientSymbols.TryGetValue(mvid, out pdbPath))
			{
				_symbolWaiters.TryRemove(mvid, out _);
			}
			else
			{
				_logger?.Invoke($"TryGetClientSymbols: asking the client for symbols of '{moduleInfo.ModuleName}' ({mvid})");
				needed(moduleInfo.ModuleName, moduleInfo.ModulePath, mvid);
				if (!waiter.Task.Wait(ClientSymbolsTimeout))
				{
					_logger?.Invoke($"TryGetClientSymbols: no answer for '{moduleInfo.ModuleName}' after {ClientSymbolsTimeout}");
					_symbolWaiters.TryRemove(mvid, out _);
					_clientSymbols.TryAdd(mvid, null);
					return false;
				}
				pdbPath = waiter.Task.Result;
			}
		}

		if (pdbPath is null) return false;
		if (!File.Exists(pdbPath))
		{
			_logger?.Invoke($"TryGetClientSymbols: the client's PDB '{pdbPath}' does not exist");
			return false;
		}
		if (!moduleInfo.MetadataReader.TryLoadSymbols(pdbPath))
		{
			_logger?.Invoke($"TryGetClientSymbols: could not load the client's PDB '{pdbPath}'");
			return false;
		}
		return true;
	}
}
